"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Check, Minus } from "lucide-react"

import { cn } from "@/lib/utils"

/*
 * Playdesk Checkbox: a recessed well when empty; checked it becomes the same
 * moulded blue pill as the primary Button, scaled to 18px.
 */

// Base UI splits Radix's checked="indeterminate" into a separate boolean prop;
// the wrapper keeps the Radix-shaped `checked` API and maps it.
type CheckboxProps = Omit<
  CheckboxPrimitive.Root.Props,
  "className" | "checked"
> & {
  className?: string
  checked?: boolean | "indeterminate"
}

const Checkbox = React.forwardRef<HTMLButtonElement, CheckboxProps>(
  ({ className, checked, ...props }, ref) => {
    const isIndeterminate = checked === "indeterminate"
    return (
      <CheckboxPrimitive.Root
        data-slot="checkbox"
        ref={ref}
        className={cn(
          "peer size-[1.125rem] shrink-0 rounded-md border border-border",
          "bg-input [box-shadow:var(--shadow-inset)]",
          "transition-[background-image,box-shadow,border-color] duration-fast ease-out",
          "focus-visible:outline-none focus-visible:ring-[0.1875rem] focus-visible:ring-ring/35",
          "disabled:cursor-not-allowed disabled:opacity-50",
          // background-origin defaults to the padding box, so with a transparent
          // border the gradient tile repeats and its darkest end shows as a
          // hairline along the top edge. Painting from the border box removes it.
          "data-checked:border-transparent data-checked:[background-origin:border-box]",
          "data-checked:[background-image:var(--fill-primary)] data-checked:text-primary-foreground data-checked:[box-shadow:var(--shadow-primary)]",
          "data-indeterminate:border-transparent data-indeterminate:[background-origin:border-box]",
          "data-indeterminate:[background-image:var(--fill-primary)] data-indeterminate:text-primary-foreground data-indeterminate:[box-shadow:var(--shadow-primary)]",
          className
        )}
        checked={isIndeterminate ? false : checked}
        indeterminate={isIndeterminate}
        nativeButton
        render={<button type="button" />}
        {...props}
      >
        <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
          {isIndeterminate ? (
            <Minus className="size-3" strokeWidth={3} />
          ) : (
            <Check className="size-3" strokeWidth={3} />
          )}
        </CheckboxPrimitive.Indicator>
      </CheckboxPrimitive.Root>
    )
  }
)
Checkbox.displayName = "Checkbox"

export { Checkbox }
